def _read_raw_body(self) -> bytes | None:
    length_header = self.headers.get("Content-Length")
    if length_header is None:
        return None
    try:
        length = int(length_header)
    except ValueError:
        return None
    if length <= 0:
        return None
    return self.rfile.read(length)

def _read_json_object(
    self, body: bytes | None = None, *, unbounded_ints: bool = False
) -> dict[str, Any] | None:
    if body is None:
        body = self._read_raw_body()
        if body is None:
            return None
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        return None
    try:
        # 任意长度整数仅限审计序号入口；其他入口保留全局转换保护。
        parsed = json.loads(
            text,
            object_pairs_hook=_unique_object,
            parse_int=_audit_json_int if unbounded_ints else int,
        )
    except ValueError:
        return None
    if not isinstance(parsed, dict):
        return None
    return parsed

def _audit_idempotency_key(self) -> str | None:
    # 审计写入口要求恰好一个合法 Idempotency-Key：缺失、重复或格式非法
    # 均为 400/invalid_request，且不查询任何资源。
    values = self.headers.get_all("Idempotency-Key")
    if values is None or len(values) != 1:
        return None
    if IDEMPOTENCY_KEY_PATTERN.fullmatch(values[0]) is None:
        return None
    return values[0]

def _parse_sla_auth(self) -> SlaAuth | None:
    # 认证头必须存在、单值且五段结构合法；任何结构问题在资源与业务检查之前拒绝。
    values = self.headers.get_all(SLA_AUTH_HEADER)
    if values is None or len(values) != 1:
        return None
    parts = values[0].split(";")
    if len(parts) != 5:
        return None
    machine_id_text, version_text, request_time_text, nonce, signature = parts
    if SLA_AUTH_MACHINE_PATTERN.fullmatch(machine_id_text) is None:
        return None
    if DECIMAL_PATTERN.fullmatch(version_text) is None:
        return None
    key_version = _decimal_int(version_text)
    if key_version is None or key_version < 1:
        return None
    if DECIMAL_PATTERN.fullmatch(request_time_text) is None:
        return None
    request_time_ms = _decimal_int(request_time_text)
    if request_time_ms is None:
        return None
    if SLA_AUTH_NONCE_PATTERN.fullmatch(nonce) is None:
        return None
    if SLA_AUTH_SIGNATURE_PATTERN.fullmatch(signature) is None:
        return None
    return SlaAuth(
        machine_id_text,
        key_version,
        request_time_ms,
        nonce,
        signature,
        bytes.fromhex(signature),
    )

def _request_auth_signing_bytes(
    self, auth: SlaAuth, path: str, body_digest: str
) -> bytes:
    # request-auth-v1\nMETHOD\nPATH\nBODY_SHA256\nTIME\nNONCE\nVERSION\nMACHINE
    return (
        f"{SLA_AUTH_CONTEXT}\n{self.command}\n{path}\n{body_digest}\n"
        f"{auth.request_time_ms}\n{auth.nonce}\n{auth.key_version}\n"
        f"{auth.machine_id}"
    ).encode("utf-8")

def _verify_request_principal(
    self,
    database: Any,
    auth: SlaAuth,
    path: str,
    body_digest: str,
) -> None:
    # 时间窗口、密钥与严格 Ed25519 验签；签名者身份由各入口自行判定。
    now_ms = int(datetime.now(UTC).timestamp() * 1000)
    if abs(auth.request_time_ms - now_ms) > SLA_AUTH_SKEW_MS:
        raise AuthRejected(HTTPStatus.UNAUTHORIZED, "stale_request")
    latest = database.execute(
        "SELECT MAX(version) AS latest FROM machine_keys"
        " WHERE machine_id = ?",
        (auth.machine_id,),
    ).fetchone()
    key = database.execute(
        "SELECT public_key, revoked FROM machine_keys"
        " WHERE machine_id = ? AND version = ?",
        (auth.machine_id, auth.key_version),
    ).fetchone()
    signature_valid = False
    if (
        latest["latest"] is not None
        and latest["latest"] == auth.key_version
        and key is not None
        and not key["revoked"]
    ):
        message = self._request_auth_signing_bytes(auth, path, body_digest)
        signature_valid = ed25519_verify(
            bytes.fromhex(key["public_key"]),
            message,
            auth.signature_bytes,

def _add_sla_auth(connection: sqlite3.Connection) -> None:
    # 仅在一次性迁移（含空库首次连接）时取写锁；BEGIN IMMEDIATE 串行并发首启。
    connection.execute("BEGIN IMMEDIATE")
    try:
        if (
            connection.execute(
                "SELECT 1 FROM schema_metadata WHERE key = ?",
                (SLA_AUTH_MARKER,),
            ).fetchone()
            is not None
        ):
            # 其他连接已完成迁移，直接释放写锁。
            connection.execute("COMMIT")
            return
        # 升级前幂等记录的认证五段一律保持 NULL：作为唯一例外按原请求先行重放，
        # 不补认证数据；随机数表为空，旧记录重放不消费随机数。
        for table in AUTH_IDEMPOTENCY_TABLES:
            existing = {
                row["name"]
                for row in connection.execute(f"PRAGMA table_info({table})")
            }
            for name, declaration in (
                column.split(" ", 1) for column in AUTH_IDEMPOTENCY_COLUMNS
            ):
                if name not in existing:
                    connection.execute(
                        f"ALTER TABLE {table} ADD COLUMN {name} {declaration}"
                    )
        connection.execute(
            "INSERT INTO schema_metadata(key, value) VALUES (?, '1')",
            (SLA_AUTH_MARKER,),
        )
        connection.execute("COMMIT")
    except BaseException:
        connection.execute("ROLLBACK")
        raise


def _backfill_delegation_events(connection: sqlite3.Connection) -> None:
    # 仅在一次性迁移（含空库首次连接）时取写锁；BEGIN IMMEDIATE 串行并发首启。
    connection.execute("BEGIN IMMEDIATE")
    try:
        if (
            connection.execute(
                "SELECT 1 FROM schema_metadata WHERE key = ?",
                (DELEGATION_EVENT_MARKER,),
            ).fetchone()
            is not None
        ):
            # 其他连接已完成迁移，直接释放写锁，不再补事件。
            connection.execute("COMMIT")
            return
        # 旧库没有 delegation_events 表（新库由 SCHEMA 创建），单事务内补齐：
        # 先按委托 rowid 升序为每张委托补一条 issued，再依现有 consumed/revoked
        # 标记紧随补 consumed/revoked；时间一律记零，不改动委托与幂等等既有数据。
        event_seq = 0
        rows = connection.execute(
            "SELECT rowid AS rid, id, consumed, revoked FROM machine_delegations"
            " ORDER BY rowid ASC"
        ).fetchall()
        for row in rows:
            event_seq += 1
            connection.execute(
                "INSERT INTO delegation_events(event_seq, delegation_id, type,"
                " created_at_ms) VALUES (?, ?, 'issued', 0)",
                (event_seq, row["id"]),
            )
            if row["consumed"]:
                event_seq += 1
                connection.execute(
                    "INSERT INTO delegation_events(event_seq, delegation_id, type,"
                    " created_at_ms) VALUES (?, ?, 'consumed', 0)",
                    (event_seq, row["id"]),
                )
            if row["revoked"]:
                event_seq += 1
                connection.execute(
                    "INSERT INTO delegation_events(event_seq, delegation_id, type,"
                    " created_at_ms) VALUES (?, ?, 'revoked', 0)",
                    (event_seq, row["id"]),
                )
        connection.execute(
            "INSERT INTO schema_metadata(key, value) VALUES (?, '1')",
            (DELEGATION_EVENT_MARKER,),
        )
        connection.execute(
            f"CREATE INDEX IF NOT EXISTS {DELEGATION_EVENT_INDEX}"
            " ON delegation_events(delegation_id, event_seq)"
        )
        connection.execute("COMMIT")
    except BaseException:
        connection.execute("ROLLBACK")
        raise


