def connect(path: str) -> sqlite3.Connection:
    database = Path(path)
    database.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(database, isolation_level=None)
    connection.row_factory = sqlite3.Row
    connection.executescript(SCHEMA)
    # 快速路径：一次性标记已存在则纯读，避免给普通读请求加写锁；
    # 标记与唯一索引在同一事务写入，故标记存在即索引已就绪。
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (TELEMETRY_SEQ_MARKER,),
        ).fetchone()
        is None
    ):
        _renumber_commit_seq(connection)
    # 此处 commit_seq 必然存在：新库由 SCHEMA 建列，旧库由迁移补列。
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_sla_telemetry_commit"
        " ON sla_telemetry_events(sla_id, commit_seq, timestamp_ms, event_id)"
    )
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (TELEMETRY_SIGNATURE_MARKER,),
        ).fetchone()
        is None
    ):
        _add_telemetry_signature_column(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (TELEMETRY_KEY_VERSION_MARKER,),
        ).fetchone()
        is None
    ):
        _add_telemetry_key_version_column(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (EVALUATION_SEQ_MARKER,),
        ).fetchone()
        is None
    ):
        _renumber_evaluation_seq(connection)
    # 此处 evaluation_seq 必然存在：新库由 SCHEMA 建列，旧库由迁移补列。
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_sla_evaluation_seq"
        " ON sla_evaluation_idempotency_records(sla_id, evaluation_seq)"
    )
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (DISPUTE_EVENT_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_dispute_events(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (MACHINE_KEYS_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_machine_keys(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (SLA_AUTH_MARKER,),
        ).fetchone()
        is None
    ):
        _add_sla_auth(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (DELEGATION_EVENT_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_delegation_events(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (DELEGATION_SCOPE_MARKER,),
        ).fetchone()
        is None
    ):
        _add_delegation_scope(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (DELEGATION_DISPUTE_MARKER,),
        ).fetchone()
        is None
    ):
        _add_delegation_dispute(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (DELEGATION_PROOF_MARKER,),
        ).fetchone()
        is None
    ):
        _add_delegation_proof(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (AUDIT_CHAIN_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_audit_comparison_chain(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (PROOF_CHECK_CHAIN_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_proof_check_chain(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (PROOF_CHECK_PROOF_CHAIN_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_proof_check_proof_chain(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (FINAL_AUDIT_PROOF_CHAIN_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_final_audit_proof_chain(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (FINAL_AUDIT_VERIFICATION_PROOF_CHAIN_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_final_audit_verification_proof_chain(connection)
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (FINAL_AUDIT_VERIFICATION_PROOF_VERIFICATION_PROOF_CHAIN_MARKER,),
        ).fetchone()
        is None
    ):
        _backfill_final_audit_verification_proof_verification_proof_chain(
            connection
        )
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (
                FINAL_AUDIT_VERIFICATION_PROOF_VERIFICATION_PROOF_VERIFICATION_PROOF_CHAIN_MARKER,
            ),
        ).fetchone()
        is None
    ):
        _backfill_final_audit_verification_proof_verification_proof_verification_proof_chain(
            connection
        )
    if (
        connection.execute(
            "SELECT 1 FROM schema_metadata WHERE key = ?",
            (
                FINAL_AUDIT_VERIFICATION_PROOF_VERIFICATION_PROOF_VERIFICATION_PROOF_VERIFICATION_PROOF_CHAIN_MARKER,
            ),
        ).fetchone()
        is None
    ):
        _backfill_final_audit_verification_proof_verification_proof_verification_proof_verification_proof_chain(
            connection
        )
    # 委托按签发事件序号分页：事件表 join 委托后需 (issuer, issued_seq) 索引。
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_delegation_events_delegation_seq"
        " ON delegation_events(delegation_id, event_seq)"
    )
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_machine_delegations_issuer"
        " ON machine_delegations(issuer_machine_id, id)"
    )
    # 消费审计按全库事件序号升序扫描某签发机器的 consumed 事件：type+seq 索引。
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_delegation_events_consumed_seq"
        " ON delegation_events(type, event_seq)"
    )
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_settlements_sla_seq"
        " ON settlements(sla_id, settlement_seq)"
    )
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_ledger_entries_account_seq"
        " ON ledger_entries(account_id, entry_seq)"
    )
    connection.execute(
        "CREATE INDEX IF NOT EXISTS idx_disputes_payee_state"
        " ON disputes(payee_id, state)"
    )
    return connection

def _create_settlement_batch(self) -> None:
    # 批次写入口要求恰好一个合法 Idempotency-Key：缺失、重复或格式非法
    # 均为 400/invalid_request，且不查询任何资源。
    values = self.headers.get_all("Idempotency-Key")
    if values is None or len(values) != 1:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    idempotency_key = values[0]
    if IDEMPOTENCY_KEY_PATTERN.fullmatch(idempotency_key) is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    fields = self._read_settlement_batch_object()
    if fields is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    status, payload = self._apply_settlement_batch(idempotency_key, fields)
    self._json(status, payload)

def _read_settlement_batch_object(self) -> dict[str, Any] | None:
    parsed = self._read_json_object()
    if parsed is None or set(parsed) != SETTLEMENT_BATCH_FIELDS:
        return None
    batch_id = parsed["id"]
    if not isinstance(batch_id, str) or TEMPLATE_ID_PATTERN.fullmatch(batch_id) is None:
        return None
    items = parsed["items"]
    if not isinstance(items, list):
        return None
    if not 1 <= len(items) <= SETTLEMENT_BATCH_MAX_ITEMS:
        return None
    seen: set[tuple[str, int]] = set()
    normalized_items: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict) or set(item) != SETTLEMENT_BATCH_ITEM_FIELDS:
            return None
        sla_id = item["slaId"]
        if not isinstance(sla_id, str) or TEMPLATE_ID_PATTERN.fullmatch(sla_id) is None:
            return None
        evaluation_seq = item["evaluationSeq"]
        if not isinstance(evaluation_seq, int) or isinstance(evaluation_seq, bool):
            return None
        if evaluation_seq < 1:
            return None
        reference = (sla_id, evaluation_seq)
        if reference in seen:
            return None
        seen.add(reference)
        normalized_items.append(
            {"slaId": sla_id, "evaluationSeq": evaluation_seq}
        )
    return {"id": batch_id, "items": normalized_items}

def _apply_settlement_batch(
    self, idempotency_key: str, fields: dict[str, Any]
) -> tuple[HTTPStatus, dict[str, Any]]:
    request_json = json.dumps(fields, sort_keys=True, separators=(",", ":"))
    batch_id = fields["id"]
    items = fields["items"]
    with closing(connect(self.server.database_path)) as database:
        database.execute("BEGIN IMMEDIATE")
        try:
            record = database.execute(
                "SELECT batch_id, request_json, status, response_json"
                " FROM settlement_batch_idempotency_records WHERE key = ?",
                (idempotency_key,),
            ).fetchone()
            if record is not None:
                database.execute("ROLLBACK")
                if (
                    record["batch_id"] == batch_id
                    and record["request_json"] == request_json
                ):
                    return HTTPStatus(record["status"]), json.loads(
                        record["response_json"]
                    )
                return HTTPStatus.CONFLICT, {"error": "conflict"}
            existing_batch = database.execute(
                "SELECT 1 FROM settlement_batches WHERE id = ?",
                (batch_id,),
            ).fetchone()
            if existing_batch is not None:
                database.execute("ROLLBACK")
                return HTTPStatus.CONFLICT, {"error": "batch_exists"}
            # 按数组顺序沿用单笔结算规则逐项判定；前项余额可供后项使用，
            # 故余额读取后以 working_balances 贯穿整批，仅在提交时落库。
            working_balances: dict[str, int] = {}

            def account_balance(account_id: str) -> int:
                if account_id not in working_balances:
                    row = database.execute(
                        "SELECT balance_micros FROM ledger_accounts"
                        " WHERE account_id = ?",
                        (account_id,),
                    ).fetchone()
                    working_balances[account_id] = (
                        row["balance_micros"] if row is not None else 0
                    )
                return working_balances[account_id]

            planned: list[dict[str, Any]] = []
            for item in items:
                sla_id = item["slaId"]
                evaluation_seq = item["evaluationSeq"]
                sla = database.execute(
                    "SELECT machine_id, consumer_id, price_micros, state"
                    " FROM slas WHERE id = ?",
                    (sla_id,),
                ).fetchone()
                if sla is None:
                    database.execute("ROLLBACK")
                    return HTTPStatus.NOT_FOUND, {"error": "not_found"}
                if sla["state"] not in ("active", "sealed"):
                    database.execute("ROLLBACK")
                    return HTTPStatus.CONFLICT, {"error": "conflict"}
                evaluation = None
                if evaluation_seq <= INT64_MAX:
                    evaluation = database.execute(
                        "SELECT sla_id, response_json"
                        " FROM sla_evaluation_idempotency_records"
                        " WHERE evaluation_seq = ?",
                        (evaluation_seq,),
                    ).fetchone()
                if evaluation is None:
                    database.execute("ROLLBACK")
